index 077aeda..c394338 100644
--- a/src/knownhost.c
+++ b/src/knownhost.c
@@ -375,6 +375,208 @@ int libssh2_knownhost_addc(LIBSSH2_KNOWNHOSTS *hosts,
  * LIBSSH2_KNOWNHOST_CHECK_MATCH
  * LIBSSH2_KNOWNHOST_CHECK_MISMATCH
